# Claim bonus tests #
hint "claiming bonus adds to total"
test
let h1 = (crop = Moonmelon, quality = Gold, quantity = 1) in
let h2 = (crop = Starfruit, quality = Gold, quantity = 1) in
let ledger = run(initModel, [
RecordHarvest(h1),
RecordHarvest(h2),
ClaimBonus
]) in
ledger.streakBonus == 0
end;

# Close day tests #
hint "closing day resets streak tracking"
test
let h1 = (crop = Moonmelon, quality = Gold, quantity = 1) in
let h2 = (crop = Starfruit, quality = Gold, quantity = 1) in
let ledger = run(initModel, [
RecordHarvest(h1),
RecordHarvest(h2),
CloseDay
]) in
ledger.streakBonus == 0 && ledger.lastQuality == Bronze
end;

# lastQuality tracking tests #
hint "lastQuality tracks most recent harvest quality"
test
let h = (crop = Moonmelon, quality = Starlight, quantity = 1) in
let ledger = update(initModel, RecordHarvest(h)) in
ledger.lastQuality == Starlight
end;

# Crop value tests #
hint "starfruit/nightshade have highest base value"
test
let h1 = (crop = Nightshade, quality = Bronze, quantity = 1) in
let h2 = (crop = Moonmelon, quality = Bronze, quantity = 1) in
let ledger1 = update(initModel, RecordHarvest(h1)) in
let ledger2 = update(initModel, RecordHarvest(h2)) in
ledger1.totalValue > ledger2.totalValue
end;

hint "duskwheat has lowest base value"
test
let h1 = (crop = Duskwheat, quality = Bronze, quantity = 1) in
let h2 = (crop = Moonmelon, quality = Bronze, quantity = 1) in
let ledger1 = update(initModel, RecordHarvest(h1)) in
let ledger2 = update(initModel, RecordHarvest(h2)) in
ledger1.totalValue < ledger2.totalValue
end;

# Quantity tests #
hint "quantity multiplies value"
test
let h = (crop = Moonmelon, quality = Bronze, quantity = 5) in
let ledger = update(initModel, RecordHarvest(h)) in
ledger.totalValue == 75
end;

